    {"rank": 3, "pr": "acme/orders#4398", "title_context": "BREAKING: rename test helper", "score": 9.5, "signals": {"modules_touched": 3, "public_api_delta": 0, "dependency_changes": 0, "contract_changes": 1, "infra_or_config_changes": 1}, "changed_lines": 220, "read_minutes": 8, "outcome": "pending"},
    {"rank": 4, "pr": "acme/payments#77", "title_context": "migration: split ledger table", "score": 8.5, "signals": {"modules_touched": 4, "public_api_delta": 0, "dependency_changes": 0, "contract_changes": 1, "infra_or_config_changes": 1}, "changed_lines": 190, "read_minutes": 7, "outcome": "pending"}
  ],
  "deferred": [
    {"pr": "acme/orders#4405", "score": 8.2, "signals": {"modules_touched": 6, "public_api_delta": 0, "dependency_changes": 0.5, "contract_changes": 0, "infra_or_config_changes": 1}, "changed_lines": 1450, "read_minutes": 36}
  ],
  "exclusions": {"population_total": 143, "bot_authors": 31, "reverts": 2, "docs_only": 17, "generated_files": 4, "below_threshold": 84},
  "merged_without_review": [
    {"pr": "acme/billing#899", "score": 11.0, "merged_at": "2026-09-04T22:41:00Z", "merged_by": "swe:dpark"}
  ],
  "previous_precision": {"hits": 3, "n": 4, "value": 0.75},
  "weights_changed": false,
  "evidence": [
    "https://ci.example.com/arch-rank/run/2026-09-08",
    "https://github.com/acme/orders/blob/main/.arch/public-api-paths.yaml",
    "https://wiki.example.com/arch-review/2026-09-01"
  ]
}

